# Tek nöron: ağırlıklı toplam + aktivasyon
import math

def sigmoid(x):
    return 1 / (1 + math.exp(-x))

def noron(girisler, agirliklar, egrri):
    toplam = sum(g * a for g, a in zip(girisler, agirliklar)) + egrri
    return sigmoid(toplam)

# 2 giriş, 2 ağırlık
sonuc = noron([0.5, 0.8], [0.4, 0.7], -0.5)
print(f'Çıkış: {sonuc:.4f}')
